export type SoundId = (typeof SOUND_IDS)[number]
export type SoundChannel = 'sfx' | 'voice' | 'music'
export type MusicId = Extract<SoundId, `music-${string}`>
export type VoiceId = Extract<SoundId, `narr-${string}`>

export const MUSIC_IDS: readonly MusicId[] = SOUND_IDS.filter((id): id is MusicId => id.startsWith('music-'))
export const VOICE_IDS: readonly VoiceId[] = SOUND_IDS.filter((id): id is VoiceId => id.startsWith('narr-'))
/** Everything that is decoded into memory up front (the music streams instead). */
export const SHORT_IDS: readonly SoundId[] = SOUND_IDS.filter((id) => !id.startsWith('music-') && !id.startsWith('amb-'))

export function channelFor(id: SoundId): SoundChannel {
  if (id.startsWith('music-') || id.startsWith('amb-')) return 'music'
  if (id.startsWith('narr-')) return 'voice'
  return 'sfx'
}

/** public/audio/<id>.mp3 under Vite's base path. */
export function audioUrl(id: string): string {
  return `${import.meta.env.BASE_URL}audio/${id}.mp3`
}

export const TRIMS_URL = `${import.meta.env.BASE_URL}audio/trims.json`
